// pwa-install.js is generated by the shared make-pwa script and is out of scope here.
// Every animation/transition duration and delay is a multiple of --dur-scale (slow-motion knob), in CSS and in JS.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const pub = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'public');
const read = (f) => fs.readFileSync(path.join(pub, f), 'utf8');
const DECL = /(?<![\w-])(animation|animation-duration|animation-delay|transition|transition-duration|transition-delay)\s*:([^;{}]*)/g;
const LIT = /(?<![\w.-])(\d*\.?\d+)(ms|s)\b/g;
const WRAPPED = /calc\(\s*[\d.]+m?s\s*\*\s*var\(--dur-scale\)\s*\)/g;

function styleBlocks(f) {
  const s = read(f);
  if (!f.endsWith('.html')) return [s];
  return [...s.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/g)].map((m) => m[1]);
}
function jsTemplates(f) {
  return [...read(f).matchAll(/`[^`]*`/g)].map((m) => m[0]).filter((t) => /animation|transition/.test(t) && /\{[^}]*\}/.test(t) && !/\$\{[^}]*\bmatch/.test(t));
}
function ctxAt(src, pos) {
  const stack = []; let pre = 0;
  for (let k = 0; k < pos; k++) {
    const c = src[k];
    if (c === '{') { stack.push(src.slice(pre, k)); pre = k + 1; } else if (c === '}') { stack.pop(); pre = k + 1; } else if (c === ';') pre = k + 1;
  }
  return stack.join('|');
}
function offenders(src) {
  const bad = [];
  for (const m of src.matchAll(DECL)) {
    if (/prefers-reduced-motion|data-fx="off"/.test(ctxAt(src, m.index))) continue;
    const v = m[2].replace(WRAPPED, '');
    for (const l of v.matchAll(LIT)) if (!/^0*\.?0+$/.test(l[1])) bad.push(`${m[1]}:${m[2].trim()}`);
  }
  return bad;
}

test(':root defines --dur-scale: 1.5', () => {
  const css = read('styles.css');
  const root = /:root\s*\{[\s\S]*?\n\}/.exec(css)[0];
  assert.match(root, /--dur-scale:\s*1\.5\s*;/);
});

test('no raw durations/delays in CSS', () => {
  for (const f of ['styles.css', 'redesign.css', 'index.html']) {
    for (const b of styleBlocks(f)) assert.deepEqual(offenders(b), [], f);
  }
});

test('no raw durations/delays in CSS-in-JS templates', () => {
  for (const f of fs.readdirSync(path.join(pub, 'js')).map((x) => `js/${x}`).filter((x) => x.endsWith('.js'))) {
    for (const t of jsTemplates(f)) assert.deepEqual(offenders(t), [], f);
  }
});

test('the offender scan catches a raw literal', () => {
  assert.equal(offenders('.a{animation:x 200ms ease}').length, 1);
  assert.equal(offenders('.a{transition:opacity calc(200ms * var(--dur-scale))}').length, 0);
  assert.equal(offenders('@media (prefers-reduced-motion:reduce){.a{animation:x 200ms}}').length, 0);
  assert.equal(offenders('html[data-fx="off"] .a{transition:opacity 120ms}').length, 0);
});

test('motion JS routes waits and animation timings through dur()', () => {
  const fx = read('js/fx.js');
  assert.match(fx, /export const dur\b/);
  assert.match(read('js/motion.js'), /export \{[^}]*\bdur\b/);
  assert.match(fx, /setTimeout\(\(\) => el\.remove\(\), dur\(ms\)\)/);
  assert.match(fx, /delay = dur\(600\)/);
  assert.match(fx, /const len = dur\(450\)/);
  assert.match(read('js/host.js'), /FLIP_MS = dur\(400\)/);
  for (const f of ['js/fx.js', 'js/motion.js', 'js/flair.js', 'js/graveyard.js']) {
    const s = read(f);
    assert.doesNotMatch(s, /\.animate\(/, `${f}: Web Animations need dur()`);
    for (const m of s.matchAll(/(?:setTimeout\([^;\n]*?,\s*|duration:\s*)(\d+)\b/g)) {
      assert.equal(m[1], '0', `${f}: raw timing ${m[0]}`);
    }
  }
});
